    28	import org.slf4j.LoggerFactory;
    29	
    30	import static org.apache.hadoop.hdfs.server.federation.router.RBFConfigKeys.DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT;
    31	import static org.apache.hadoop.hdfs.server.federation.router.RBFConfigKeys.DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT_DEFAULT;
    32	
    33	/**
    34	 * Base fairness policy that implements @RouterRpcFairnessPolicyController.
    35	 * Internally a map of nameservice to Semaphore is used to control permits.
    36	 */
    37	public class AbstractRouterRpcFairnessPolicyController
    38	    implements RouterRpcFairnessPolicyController {
    39	
    40	  private static final Logger LOG =
    41	      LoggerFactory.getLogger(AbstractRouterRpcFairnessPolicyController.class);
    42	
    43	  /** Hash table to hold semaphore for each configured name service. */
    44	  private Map<String, Semaphore> permits;
    45	
    46	  /** Max time to wait for a permit. */
    47	  private long acquireTimeoutMs = DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT_DEFAULT;
    48	
    49	  public void init(Configuration conf) {
    50	    this.permits = new HashMap<>();
    51	    long timeoutMs = conf.getTimeDuration(DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT,
    52	        DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT_DEFAULT, TimeUnit.MILLISECONDS);
    53	    if (timeoutMs >= 0) {
    54	      this.acquireTimeoutMs = timeoutMs;
    55	    } else {
    56	      LOG.warn("Invalid value {} configured for {} should be greater than or "
    57	              + "equal to 0, using default value of {} instead.", timeoutMs,
    58	          DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT,
    59	          DFS_ROUTER_FAIRNESS_ACQUIRE_TIMEOUT_DEFAULT);
    60	    }
    61	  }
    62	
    63	  @Override
    64	  public boolean acquirePermit(String nsId) {
    65	    try {
    66	      LOG.debug("Taking lock for nameservice {}", nsId);
    67	      return this.permits.get(nsId)
    68	          .tryAcquire(this.acquireTimeoutMs, TimeUnit.MILLISECONDS);
    69	    } catch (InterruptedException e) {
    70	      LOG.debug("Cannot get a permit for nameservice {}", nsId);
    71	    }
    72	    return false;
    73	  }
    74	
    75	  @Override
    76	  public void releasePermit(String nsId) {
    77	    this.permits.get(nsId).release();
    78	  }
    79	
    80	  @Override
    81	  public void shutdown() {
    82	    // drain all semaphores
    83	    for (Semaphore sema: this.permits.values()) {
    84	      sema.drainPermits();
    85	    }
    86	  }
    87	
    88	  protected void insertNameServiceWithPermits(String nsId, int maxPermits) {
    89	    this.permits.put(nsId, new Semaphore(maxPermits));
    90	  }
    91	
    92	  protected int getAvailablePermits(String nsId) {
    93	    return this.permits.get(nsId).availablePermits();
    94	  }
    95	}
